import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  rectSortingStrategy,
  useSortable,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { toFormData } from "@/utils/form-data-mapper";

export const Route = createFileRoute("/(core)/back-office/team-members/")({
  beforeLoad: async ({ context }) =>
    await requirePermission(context, {
      permission: "banners.view",
    }),
  component: TeamMembersManagementPage,
  head: () => pageHead("Manajemen Tim Kami"),
});

const SOCIAL_ICON_MAP: Record<string, any> = {
  linkedin: IconBrandLinkedin,
  email: IconMail,
  instagram: IconBrandInstagram,
  twitter: IconBrandTwitter,
  github: IconBrandGithub,
};

function SortableTeamMemberCard({
  member,
  index,
  onToggleActive,
  onDelete,
}: {
  member: any;
  index: number;
  onToggleActive: (member: any) => void;
  onDelete: (id: string) => void;
}) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: member.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  const socialLinks: Array<{ platform: string; url: string; label: string }> =
    Array.isArray(member.socialLinks) ? member.socialLinks : [];

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`group relative flex flex-col overflow-hidden rounded-2xl border bg-white shadow-xs transition-all duration-200 hover:shadow-md ${
        isDragging
          ? "z-50 scale-105 border-blue-500 opacity-80 shadow-2xl"
          : "border-slate-200"
      }`}
    >
      {/* Drag Handle Button */}
      <div
        {...attributes}
        {...listeners}
        className="absolute top-3 left-3 z-10 flex cursor-grab items-center gap-1.5 rounded-xl bg-black/60 px-2.5 py-1.5 text-xs font-bold text-white backdrop-blur-xs transition hover:bg-black/80 active:cursor-grabbing"
        title="Tarik untuk mengubah urutan"
      >
        <IconGripVertical className="h-4 w-4" />
        <span>#{index + 1}</span>
      </div>

      {/* Status Badge */}
      <div className="absolute top-3 right-3 z-10">
        {member.isActive ? (
          <Badge className="border-0 bg-emerald-500 font-semibold text-white shadow-xs">
            Aktif
          </Badge>
        ) : (
          <Badge className="border-0 bg-slate-500 font-semibold text-white shadow-xs">
            Non-aktif
          </Badge>
        )}
      </div>

      {/* Photo Preview Box */}
      <div className="relative aspect-[4/3] w-full overflow-hidden bg-slate-100">
        {member.photoUrl ? (
          <ImageWithFallback
            src={getPublicUrl(member.photoUrl)}
            alt={member.name}
            className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-105"
          />
        ) : (
          <div className="flex h-full w-full items-center justify-center bg-slate-200 text-slate-400">
            <IconUsers className="h-16 w-16" />
          </div>
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent" />
        <div className="absolute right-3 bottom-3 left-3">
          <p className="line-clamp-1 text-base font-bold text-white drop-shadow-md">
            {member.name}
          </p>
          <p className="line-clamp-1 text-xs font-medium text-slate-200 drop-shadow-xs">
            {member.role}
          </p>
        </div>
      </div>

      {/* Bio & Social Links Preview */}
      <div className="flex-1 space-y-2 p-4">
        {member.bio ? (
          <p className="line-clamp-2 text-xs text-slate-600">{member.bio}</p>
        ) : (
          <p className="text-xs text-slate-400 italic">Tidak ada bio singkat</p>
        )}

        {/* Social Links Icons */}
        <div className="flex flex-wrap items-center gap-1.5 pt-1">
          {socialLinks.length > 0 ? (
            socialLinks.map((link, idx) => {
              const IconComponent =
                SOCIAL_ICON_MAP[link.platform.toLowerCase()] || IconWorld;
              return (
                <span
                  key={idx}
                  title={`${link.label}: ${link.url}`}
                  className="flex items-center gap-1 rounded-md bg-slate-100 px-2 py-0.5 text-[11px] font-medium text-slate-700"
                >
                  <IconComponent className="h-3.5 w-3.5 text-slate-500" />
                  <span className="capitalize">
                    {link.label || link.platform}
                  </span>
                </span>
              );
            })
          ) : (
            <span className="text-[11px] text-slate-400 italic">
              Belum ada link sosial media
            </span>
          )}
        </div>
      </div>

      {/* Action Footer */}
      <div className="flex items-center justify-between border-t border-slate-100 bg-slate-50/50 px-4 py-3">
        <button
          type="button"
          onClick={() => onToggleActive(member)}
          className={`flex items-center gap-1.5 rounded-lg px-2.5 py-1 text-xs font-bold transition ${
            member.isActive
              ? "text-amber-700 hover:bg-amber-100/60"
              : "text-emerald-700 hover:bg-emerald-100/60"
          }`}
        >
          {member.isActive ? (
            <>
              <IconEyeOff className="h-3.5 w-3.5" />
              Sembunyikan
            </>
          ) : (
            <>
              <IconEye className="h-3.5 w-3.5" />
              Tampilkan
            </>
          )}
        </button>

        <div className="flex items-center gap-1">
          <PermissionGate permission="banners.update">
            <Link
              to="/back-office/team-members/$memberId/edit"
              params={{ memberId: member.id }}
            >
              <Button
                variant="ghost"
                size="icon-sm"
                className="h-8 w-8 text-slate-600 hover:bg-slate-200/60 hover:text-slate-900"
                title="Edit data anggota"
              >
                <IconEdit className="h-4 w-4" />
              </Button>
            </Link>
          </PermissionGate>

          <PermissionGate permission="banners.delete">
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={() => onDelete(member.id)}
              className="h-8 w-8 text-red-600 hover:bg-red-50 hover:text-red-700"
              title="Hapus anggota"
            >
              <IconTrash className="h-4 w-4" />
            </Button>
          </PermissionGate>
        </div>
      </div>
    </div>
  );
}

function TeamMembersManagementPage() {
  const queryClient = useQueryClient();

  const { data: teamMembersData, isLoading } = useQuery(
    trpc.platform.teamMember.getAllTeamMembersForAdmin.queryOptions(),
  );

  const [items, setItems] = useState<any[]>([]);

  useEffect(() => {
    if (teamMembersData) {
      setItems(teamMembersData);
    }
  }, [teamMembersData]);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  const reorderMutation = useMutation({
    ...trpc.platform.teamMember.reorderTeamMembers.mutationOptions(),
    onSuccess: () => {
      globalSuccessToast("Urutan anggota tim berhasil disimpan!");
      queryClient.invalidateQueries(
        trpc.platform.teamMember.getAllTeamMembersForAdmin.queryOptions(),
      );
      queryClient.invalidateQueries(
        trpc.platform.teamMember.getAllTeamMembers.queryOptions(),
      );
    },
    onError: (err) => {
      globalErrorToast(`Gagal memperbarui urutan: ${err.message}`);
      if (teamMembersData) setItems(teamMembersData);
    },
  });

  const toggleActiveMutation = useMutation({
    ...trpc.platform.teamMember.updateTeamMember.mutationOptions(),
    onSuccess: () => {
      globalSuccessToast("Status visibilitas berhasil diperbarui!");
      queryClient.invalidateQueries(
        trpc.platform.teamMember.getAllTeamMembersForAdmin.queryOptions(),
      );
      queryClient.invalidateQueries(
        trpc.platform.teamMember.getAllTeamMembers.queryOptions(),
      );
    },
    onError: (err) => {
      globalErrorToast(`Gagal mengubah status: ${err.message}`);
    },
  });

  const deleteMutation = useMutation({
    ...trpc.platform.teamMember.deleteTeamMember.mutationOptions(),
    onSuccess: () => {
      globalSuccessToast("Anggota tim berhasil dihapus!");
      queryClient.invalidateQueries(
        trpc.platform.teamMember.getAllTeamMembersForAdmin.queryOptions(),
      );
      queryClient.invalidateQueries(
        trpc.platform.teamMember.getAllTeamMembers.queryOptions(),
      );
    },
    onError: (err) => {
      globalErrorToast(`Gagal menghapus anggota tim: ${err.message}`);
    },
  });

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      setItems((prevItems) => {
        const oldIndex = prevItems.findIndex((item) => item.id === active.id);
        const newIndex = prevItems.findIndex((item) => item.id === over.id);
        const newArray = arrayMove(prevItems, oldIndex, newIndex);

        const payload = newArray.map((item, idx) => ({
          id: item.id,
          order: idx,
        }));

        reorderMutation.mutate({ items: payload });
        return newArray;
      });
    }
  };

  const handleToggleActive = (member: any) => {
    const formData = toFormData({
      id: member.id,
      isActive: !member.isActive,
    });
    toggleActiveMutation.mutate(formData);
  };

  const handleDelete = (id: string) => {
    if (confirm("Apakah Anda yakin ingin menghapus anggota tim ini?")) {
      deleteMutation.mutate({ id });
    }
  };

  return (
    <div className="mx-auto max-w-6xl space-y-6 px-2 py-4">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight text-slate-800">
            Manajemen Tim Kami
          </h1>
          <p className="text-sm font-medium text-slate-500">
            Kelola profil anggota tim yang ditampilkan pada halaman Tim Kami
            (Credit).
          </p>
        </div>

        <PermissionGate permission="banners.create">
          <Link to="/back-office/team-members/create">
            <Button className="gap-2 bg-blue-600 font-bold hover:bg-blue-700">
              <IconPlus className="h-4 w-4" />
              Tambah Anggota Tim
            </Button>
          </Link>
        </PermissionGate>
      </div>

      {/* Info Notification */}
      <div className="flex items-start gap-3 rounded-2xl border border-blue-100 bg-blue-50/60 p-4 text-sm text-blue-900">
        <IconAlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-blue-600" />
        <div>
          <p className="font-bold">Tips Urutan Kartu Profil:</p>
          <p className="text-xs text-blue-700">
            Tarik tombol <strong>Grip / #Nomor</strong> pada kartu anggota tim
            untuk mengatur urutan tampil di halaman publik secara otomatis.
          </p>
        </div>
      </div>

      {/* Content */}
      {isLoading ? (
        <div className="flex h-64 items-center justify-center">
          <Spinner className="h-8 w-8 text-blue-600" />
        </div>
      ) : items.length === 0 ? (
        <div className="flex flex-col items-center justify-center rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50/50 py-16 text-center">
          <div className="rounded-full bg-slate-100 p-4 text-slate-400">
            <IconUsers className="h-10 w-10" />
          </div>
          <h3 className="mt-4 text-base font-bold text-slate-800">
            Belum ada data anggota tim
          </h3>
          <p className="mt-1 text-xs text-slate-500">
            Mulai tambahkan anggota tim Anda sekarang untuk ditampilkan di
            halaman Tim Kami.
          </p>
          <PermissionGate permission="banners.create">
            <Link to="/back-office/team-members/create" className="mt-4">
              <Button
                size="sm"
                className="gap-2 bg-blue-600 font-bold hover:bg-blue-700"
              >
                <IconPlus className="h-4 w-4" />
                Tambah Anggota Sekarang
              </Button>
            </Link>
          </PermissionGate>
        </div>
      ) : (
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext
            items={items.map((i) => i.id)}
            strategy={rectSortingStrategy}
          >
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {items.map((member, index) => (
                <SortableTeamMemberCard
                  key={member.id}
                  member={member}
                  index={index}
                  onToggleActive={handleToggleActive}
                  onDelete={handleDelete}
                />
              ))}
            </div>
          </SortableContext>
        </DndContext>
      )}
    </div>
  );
}

